function solve(nums, k) {
  const target = nums.length - k;
  let lo = 0;
  let hi = nums.length - 1;
  const a = nums.slice();
  while (lo <= hi) {
    const pivot = a[hi];
    let store = lo;
    for (let i = lo; i < hi; i++) {
      if (a[i] < pivot) { [a[store], a[i]] = [a[i], a[store]]; store++; }
    }
    [a[store], a[hi]] = [a[hi], a[store]];
    if (store === target) return a[store];
    if (store < target) lo = store + 1;
    else hi = store - 1;
  }
  return -1;
}
